export const PMS_CATEGORIES = ["All PMS","Large Cap","Mid Cap","Small Cap","Multi Cap","Mid & Small Cap","Multi Asset","Thematic"] as const;
export const AIF_CATEGORIES = ["All AIF","Category I","Category II","CAT II Debt","Category III","CAT III Long Short","CAT III Long Only"] as const;

export function getProduct(slug: string) {
  return PRODUCTS.find((p) => p.slug === slug);
}

export function productsByKind(kind: ProductKind) {
  return PRODUCTS.filter((p) => p.kind === kind);
}

export function featuredProducts(kind?: ProductKind, take = 18) {
  const pool = kind ? productsByKind(kind) : PRODUCTS;
  return [...pool].sort((a, b) => b.q + b.c - (a.q + a.c)).slice(0, take);
}

export function searchProducts(query: string) {
  const q = query.trim().toLowerCase();
  if (!q) return PRODUCTS.slice(0, 24);
  return PRODUCTS.filter(
    (p) =>
      p.name.toLowerCase().includes(q) ||
      p.category.toLowerCase().includes(q) ||
      p.style.toLowerCase().includes(q) ||
      p.kind.toLowerCase().includes(q)
  ).slice(0, 40);
}